use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut last_key = None;
    let mut last_value = None;

    for item in input.as_array() {
        let key = item.as_i64().unwrap();
        let value = item.as_i64().unwrap();

        if last_key.is_none() || key != last_key {
            result.push(vec![last_key, last_value]);
            last_key = Some(key);
            last_value = Some(value);
        } else {
            last_value = Some(value);
        }
    }

    result.sort_unstable_by(|a, b| a[0].cmp(&b[0]));
    result
}
